254:     @Tool(name = "desktop_wait",
255:             description = "等待界面元素、文本、窗口、桌面生命周期事件或短暂延时就绪（单次最多 30000ms），替代盲目重试。只读。",
256:             readOnly = true)
257:     public ToolResultBlock waitCondition(
258:             @ToolParam(name = "request", description = "可选 elementRef、predicate、value、text、windowTitle、event、app、timeoutMs、delayMs") WaitRequest request,
259:             RuntimeContext context
260:     ) {
261:         try {
262:             if (request == null) throw new IllegalArgumentException("wait 请求参数不能为空");
263:             List<String> args = new ArrayList<>();
264:             args.add("wait");
265: 
266:             int timeoutMs = request.timeoutMs() == null ? 10_000 : request.timeoutMs();
267:             if (timeoutMs < 100 || timeoutMs > MAX_WAIT_MS) {
268:                 throw new IllegalArgumentException("timeoutMs 必须在 100 到 " + MAX_WAIT_MS + " 之间");
269:             }
270: 
271:             boolean hasCondition = false;
272:             if (!isBlank(request.elementRef())) {
273:                 args.add("--element");
274:                 args.add(validateRef(request.elementRef(), "elementRef"));
275:                 hasCondition = true;
276:                 if (!isBlank(request.predicate())) {
277:                     String predicate = request.predicate().strip().toLowerCase(Locale.ROOT);
278:                     if (!VALID_WAIT_PREDICATES.contains(predicate)) {
279:                         throw new IllegalArgumentException("predicate 仅支持：" + VALID_WAIT_PREDICATES);
280:                     }
281:                     args.add("--predicate");
282:                     args.add(predicate);
283:                 }
284:                 if (!isBlank(request.value())) {
285:                     args.add("--value");
286:                     args.add(validateTextValue(request.value(), "value"));
287:                 }
288:             }
289:             if (!isBlank(request.windowTitle())) {
290:                 args.add("--window");
291:                 args.add(validateTextValue(request.windowTitle(), "windowTitle"));
292:                 hasCondition = true;
293:             }
294:             if (!isBlank(request.text())) {
295:                 args.add("--text");
296:                 args.add(validateTextValue(request.text(), "text"));
297:                 hasCondition = true;
298:             }
299:             if (!isBlank(request.event())) {
300:                 String event = request.event().strip().toLowerCase(Locale.ROOT);
301:                 if (!VALID_WAIT_EVENTS.contains(event)) {
302:                     throw new IllegalArgumentException("event 仅支持：" + VALID_WAIT_EVENTS);
303:                 }
304:                 args.add("--event");
305:                 args.add(event);
306:                 hasCondition = true;
307:             }
308:             if (!isBlank(request.app())) {
309:                 args.add("--app");
310:                 args.add(validatePlainValue(request.app(), "app"));
311:             }
312: 
313:             if (hasCondition) {
314:                 args.add("--timeout");
315:                 args.add(Integer.toString(timeoutMs));
316:             } else if (request.delayMs() != null) {
317:                 int delay = request.delayMs();
318:                 if (delay < 50 || delay > MAX_WAIT_MS) {
319:                     throw new IllegalArgumentException("delayMs 必须在 50 到 " + MAX_WAIT_MS + " 之间");
320:                 }
321:                 args.add(Integer.toString(delay));
322:                 timeoutMs = delay;
323:             } else {
324:                 throw new IllegalArgumentException("至少需要指定 elementRef、windowTitle、text、event 或 delayMs 之一");
325:             }
326: 
327:             Duration processTimeout = Duration.ofMillis(timeoutMs + 5_000L);
328:             return toResult(service.invokeForTool(sessionId(context), args, null, processTimeout, false, true));
329:         } catch (IllegalArgumentException exception) {
330:             return ToolResultBlock.error(exception.getMessage());
331:         }
332:     }
