501:                         throw new IllegalArgumentException(action + " 至少需要 app 或 windowId 之一");
502:                     }
503:                 }
504:                 case "resize-window" -> {
505:                     if (request.width() == null || request.height() == null) {
506:                         throw new IllegalArgumentException("resize-window 必须提供 width 和 height");
507:                     }
508:                     if (request.width() < 100 || request.width() > 10_000
509:                             || request.height() < 100 || request.height() > 10_000) {
510:                         throw new IllegalArgumentException("窗口尺寸必须在 100 到 10000 像素之间");
511:                     }
512:                     args.add("resize-window");
513:                     if (!appendWindowTarget(args, request.app(), request.windowId())) {
514:                         throw new IllegalArgumentException("resize-window 至少需要 app 或 windowId 之一");
515:                     }
516:                     args.add("--width");
517:                     args.add(Integer.toString(request.width()));
518:                     args.add("--height");
519:                     args.add(Integer.toString(request.height()));
520:                 }
521:                 case "move-window" -> {
522:                     if (request.x() == null || request.y() == null) {
523:                         throw new IllegalArgumentException("move-window 必须提供 x 和 y");
524:                     }
525:                     if (request.x() < -10_000 || request.x() > 20_000
526:                             || request.y() < -10_000 || request.y() > 20_000) {
527:                         throw new IllegalArgumentException("窗口坐标超出合理范围");
