530:                     if (!appendWindowTarget(args, request.app(), request.windowId())) {
531:                         throw new IllegalArgumentException("move-window 至少需要 app 或 windowId 之一");
532:                     }
533:                     args.add("--x=" + request.x());
534:                     args.add("--y=" + request.y());
535:                 }
