86:         Duration effectiveTimeout = timeout == null || timeout.isNegative() || timeout.isZero()
87:                 ? Duration.ofSeconds(15)
88:                 : timeout;
89: 
90:         IOException lastStartError = null;
91:         for (String executable : candidates) {
92:             try {
93:                 return runSingleCandidate(executable, arguments, stdinText, effectiveTimeout);
94:             } catch (ProcessStartException exception) {
95:                 lastStartError = exception.ioCause;
96:             }
97:         }
98: 
99:         String hint = configuredCliPath != null && !configuredCliPath.isBlank()
100:                 ? "无法启动配置的 agent-desktop 路径（" + configuredCliPath + "），请核对文件是否存在且具备执行权限。"
101:                 : "当前电脑未找到 agent-desktop 命令，请先安装（npm install -g agent-desktop）或在设置中指定 CLI 路径。";
102:         log.debug("agent-desktop 启动失败：candidates={}, error={}", candidates,
103:                 lastStartError == null ? "none" : lastStartError.getMessage());
104:         return CliExecutionResult.notFound(hint);
105:     }
