107:     /** 按宿主机平台构造有序可执行文件候选列表。 */
108:     static List<String> resolveExecutableCandidates(String configuredCliPath, String normalizedOs) {
109:         if (configuredCliPath != null && !configuredCliPath.isBlank()) {
110:             return List.of(configuredCliPath.strip());
111:         }
112:         if ("windows".equals(normalizedOs)) {
113:             return List.of("agent-desktop.exe", "agent-desktop.cmd", "agent-desktop");
114:         }
115:         List<String> candidates = new ArrayList<>();
116:         candidates.add("agent-desktop");
117:         if ("macos".equals(normalizedOs)) {
118:             addIfExecutable(candidates, "/opt/homebrew/bin/agent-desktop");
119:             addIfExecutable(candidates, "/usr/local/bin/agent-desktop");
120:         }
121:         String userHome = System.getProperty("user.home", "");
122:         if (!userHome.isBlank()) {
123:             addIfExecutable(candidates, Path.of(userHome, ".local", "bin", "agent-desktop").toString());
124:         }
125:         return List.copyOf(candidates);
126:     }
127: 
128:     private static void addIfExecutable(List<String> candidates, String candidatePath) {
129:         try {
130:             Path path = Path.of(candidatePath);
131:             if (Files.isRegularFile(path) && Files.isExecutable(path)) {
132:                 candidates.add(candidatePath);
133:             }
134:         } catch (RuntimeException ignored) {
135:             // 忽略非法路径或权限查询异常
136:         }
