139:     private CliExecutionResult runSingleCandidate(
140:             String executable,
141:             List<String> arguments,
142:             String stdinText,
143:             Duration timeout
144:     ) throws ProcessStartException {
145:         List<String> command = new ArrayList<>(1 + (arguments == null ? 0 : arguments.size()));
146:         command.add(executable);
147:         if (arguments != null) command.addAll(arguments);
148: 
149:         ProcessBuilder builder = new ProcessBuilder(command);
150:         Process process;
151:         try {
152:             process = builder.start();
153:         } catch (IOException exception) {
154:             throw new ProcessStartException(exception);
155:         }
156: 
157:         CompletableFuture<StreamCapture> stdoutFuture = null;
158:         CompletableFuture<StreamCapture> stderrFuture = null;
159:         try {
160:             stdoutFuture = CompletableFuture.supplyAsync(() -> readStreamBounded(process.getInputStream(), MAX_STDOUT_CHARS));
161:             stderrFuture = CompletableFuture.supplyAsync(() -> readStreamBounded(process.getErrorStream(), MAX_STDERR_CHARS));
162: 
163:             try (OutputStream stdin = process.getOutputStream()) {
164:                 if (stdinText != null) {
165:                     stdin.write(stdinText.getBytes(StandardCharsets.UTF_8));
166:                     stdin.flush();
167:                 }
168:             } catch (IOException exception) {
169:                 log.debug("向 agent-desktop 写入 stdin 时子进程已提前关闭：{}", exception.getMessage());
170:             }
171: 
172:             boolean finished = process.waitFor(timeout.toMillis(), TimeUnit.MILLISECONDS);
173:             if (!finished) {
174:                 terminateProcessTree(process);
175:                 cancelFuture(stdoutFuture);
176:                 cancelFuture(stderrFuture);
177:                 return CliExecutionResult.timeout("agent-desktop 命令执行超时（上限 " + timeout.toSeconds() + " 秒）。");
178:             }
179: 
180:             StreamCapture stdout = awaitCapture(stdoutFuture);
181:             StreamCapture stderr = awaitCapture(stderrFuture);
182:             return new CliExecutionResult(
183:                     true,
184:                     false,
185:                     process.exitValue(),
186:                     stdout.text(),
187:                     stderr.text(),
188:                     stdout.truncated(),
189:                     null
190:             );
191:         } catch (InterruptedException exception) {
192:             terminateProcessTree(process);
193:             cancelFuture(stdoutFuture);
194:             cancelFuture(stderrFuture);
195:             Thread.currentThread().interrupt();
196:             throw new CommandCancelledException("桌面操作命令已取消", exception);
197:         } catch (RuntimeException exception) {
198:             terminateProcessTree(process);
199:             cancelFuture(stdoutFuture);
200:             cancelFuture(stderrFuture);
201:             throw exception;
202:         }
203:     }
204: 
205:     private static StreamCapture readStreamBounded(InputStream inputStream, int maxChars) {
206:         StringBuilder builder = new StringBuilder();
207:         boolean truncated = false;
208:         char[] buffer = new char[2048];
209:         try (BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream, StandardCharsets.UTF_8))) {
210:             int read;
211:             while ((read = reader.read(buffer)) != -1) {
212:                 if (builder.length() < maxChars) {
213:                     int remaining = maxChars - builder.length();
214:                     int toAppend = Math.min(read, remaining);
215:                     builder.append(buffer, 0, toAppend);
216:                     if (toAppend < read) truncated = true;
217:                 } else {
218:                     truncated = true;
219:                 }
220:             }
221:         } catch (IOException ignored) {
222:             // 子进程结束或被中断时正常退出读取
223:         }
224:         return new StreamCapture(builder.toString(), truncated);
225:     }
226: 
227:     private static StreamCapture awaitCapture(CompletableFuture<StreamCapture> future) throws InterruptedException {
228:         try {
229:             return future.get(3, TimeUnit.SECONDS);
230:         } catch (InterruptedException exception) {
231:             throw exception;
232:         } catch (Exception ignored) {
233:             return new StreamCapture("", false);
234:         }
235:     }
236: 
237:     private static void cancelFuture(CompletableFuture<?> future) {
238:         if (future != null) future.cancel(true);
239:     }
240: 
241:     private static void terminateProcessTree(Process process) {
242:         if (process == null || !process.isAlive()) return;
243:         process.descendants().forEach(handle -> {
244:             if (handle.isAlive()) handle.destroy();
245:         });
246:         process.destroy();
247:         if (process.isAlive()) {
248:             try {
249:                 process.waitFor(500, TimeUnit.MILLISECONDS);
250:             } catch (InterruptedException exception) {
251:                 Thread.currentThread().interrupt();
252:             }
253:         }
254:         if (process.isAlive()) {
255:             process.descendants().forEach(handle -> {
256:                 if (handle.isAlive()) handle.destroyForcibly();
257:             });
258:             process.destroyForcibly();
259:         }
260:     }
261: 
262:     private record StreamCapture(String text, boolean truncated) {}
263: 
264:     private static final class ProcessStartException extends Exception {
265:         private final IOException ioCause;
266: 
267:         private ProcessStartException(IOException ioCause) {
268:             super(ioCause);
269:             this.ioCause = ioCause;
270:         }
271:     }
272: }

